function similarityScore(base:Listing,candidate:Listing,category:Category){const value=(row:Listing,key:string,column?:string)=>row[column||key]??row.details?.[key];const equal=(a:any,b:any)=>String(a??'').trim().toLocaleLowerCase('az-AZ')===String(b??'').trim().toLocaleLowerCase('az-AZ');let score=0;if(category.source==='vehicle'){for(const [key,weight] of [['brand',6],['model',5],['body_type',3],['year',2],['region',1]] as [string,number][]){const a=value(base,key),b=value(candidate,key);if(a!=null&&a!==''&&b!=null&&equal(a,b))score+=weight;}const a=Number(priceOf(base)),b=Number(priceOf(candidate));if(Number.isFinite(a)&&a>0&&Number.isFinite(b)&&b>0&&Math.abs(a-b)/a<=.25)score+=2;}else{const fields=CATEGORY_FILTERS[category.key]||[];for(const field of fields){const a=value(base,field.key,field.column),b=value(candidate,field.key,field.column);if(a!=null&&a!==''&&b!=null&&equal(a,b))score+=2;}const baseDetails=base.details&&typeof base.details==='object'?base.details:{};for(const [key,a] of Object.entries(baseDetails)){const b=(candidate.details||{})[key];if(a!=null&&a!==''&&typeof a!=='object'&&b!=null&&equal(a,b))score+=1;}const a=Number(priceOf(base)),b=Number(priceOf(candidate));if(Number.isFinite(a)&&a>0&&Number.isFinite(b)&&b>0&&Math.abs(a-b)/a<=.3)score+=1;}return score;}

