function displayDetailValue(key:string,value:any):string|null {
 if(value==null||value==='')return null;
 if(Array.isArray(value)){const entries=value.map(item=>displayDetailValue(key,item)).filter(Boolean);return entries.join(', ')||null;}
 if(typeof value==='object'){
  return Object.entries(value).map(([name,entry],index)=>{const text=displayDetailValue(name,entry);return text?`${DETAIL_LABELS[name]||`Əlavə məlumat ${index+1}`}: ${text}`:'';}).filter(Boolean).join(' · ')||null;
 }
 if(typeof value==='boolean')return value?'Bəli':'Xeyr';
 if(key==='published_at'||key==='created_at'){const date=new Date(String(value));return Number.isNaN(date.getTime())?null:date.toLocaleDateString('az-AZ');}
 if(typeof value==='string'){const trimmed=value.trim();if((trimmed.startsWith('{')&&trimmed.endsWith('}'))||(trimmed.startsWith('[')&&trimmed.endsWith(']'))){try{return displayDetailValue(key,JSON.parse(trimmed));}catch{}}const normalized=trimmed.toLocaleLowerCase('en-US');const configured=listingFieldChoices('',key)?.find(option=>option.value.toLocaleLowerCase('en-US')===normalized||option.label.toLocaleLowerCase('en-US')===normalized);return DETAIL_VALUE_LABELS[normalized]||configured?.label||trimmed||null;}
 if(key==='engine_volume')return `${value} L`;
 if(key==='horsepower')return `${value} a.g.`;
 if(key==='mileage')return `${Number(value).toLocaleString('az-AZ')} km`;
 return String(value);
}
function Specs({item}:{item:Listing}) {
 const common:[string,any][]=[['public_number',item.public_number],['region',locationOf(item)],['district',item.district],['published_at',item.published_at||item.created_at]];
 const fieldsBySource:Record<string,string[]>={
  vehicle:['year','body_type','color','seats','engine','engine_volume','horsepower','fuel_type','transmission','drivetrain','mileage','vehicle_condition','condition','damage_condition','market','address'],
  marketplace:['brand','model','year','condition','currency','address'],
  service_provider:['title','name','specialty','services','about','experience','working_hours','message_contact','price','address'],
  auto_dealer:['dealer_name','contact_name','brands','vehicle_condition','working_hours','about','address','credit_available','leasing_available','barter_available','delivery_available']
 };
 const rootRows:[string,any][]=(fieldsBySource[item._source]||[]).map(key=>[key,item[key]] as [string,any]);
 const detailRows:[string,any][]=Object.entries(item.details||{}).filter(([key])=>!['equipment','vin','service_category'].includes(key)).map(([key,value])=>[key,value] as [string,any]);
 const rows:[string,any][]=[...common,...rootRows,...detailRows];
 const normalized=rows.map(([key,value])=>[key,displayDetailValue(key,value)] as [string,string|null]).filter((row):row is [string,string]=>Boolean(row[1])).filter(([key],i,all)=>all.findIndex(([other])=>other===key)===i);
 return <>{normalized.map(([key,value],i)=><View key={`${key}-${i}`} style={styles.spec}><Text style={styles.specKey}>{DETAIL_LABELS[key]||`Əlavə məlumat ${i+1}`}</Text><Text style={styles.specVal}>{value}</Text></View>)}</>;
}
function Equipment({item}:{item:Listing}) {const selected=selectedEquipment(item.details?.equipment,item._category);if(!selected.length)return null;return <View style={styles.detailPad}><Text style={styles.heading}>{item._source==='vehicle'?'Avtomobilin təchizatı':'Avadanlıq və imkanlar'}</Text><View style={{flexDirection:'row',flexWrap:'wrap',gap:8,marginTop:10}}>{selected.map(entry=><Text key={entry} style={[styles.pill,styles.pillText]}>{entry}</Text>)}</View></View>}
function PromotionModal({type,listing,client,onClose}:{type:PromotionType|null;listing:Listing;client:any;onClose:()=>void}){
 const [planCode,setPlanCode]=useState(type?PROMOTION_CATALOG[type].plans[0].code:''),[busy,setBusy]=useState(false);const intentRequestId=useRef('');
 if(!type)return null;
 const catalog=PROMOTION_CATALOG[type],plan=catalog.plans.find(row=>row.code===planCode)||catalog.plans[0];
 const confirm=async()=>{if(busy)return;if(!client){Alert.alert('Ödəniş xidməti qoşulmayıb','Ödəniş provayderi qoşulmadığı üçün pul tutulmur və xidmət aktivləşdirilmir.');return;}setBusy(true);try{intentRequestId.current=intentRequestId.current||newUuid();const intent=await createPromotionPaymentIntent(client,listing,plan.code,intentRequestId.current);if(intent.amountMinor!==Math.round(plan.price*100))throw new Error('Server tarifinin qiyməti dəyişib. Səhifəni yeniləyib yenidən yoxlayın.');Alert.alert('Ödəniş təsdiqlənməyib',`${catalog.name} · ${plan.label} · ${plan.price.toFixed(2)} AZN\n\nÖdəniş provayderi qoşulmadığı üçün pul tutulmayıb. Sorğu yalnız ödəniş hazırlığı kimi saxlanılıb; elan dəyişdirilmədi və paket aktiv edilmədi.`,[{text:'Bağla',onPress:onClose}]);}catch(e){Alert.alert('Ödəniş sorğusu yaradılmadı',errorText(e));}finally{setBusy(false);}};
 return <Modal visible transparent animationType="slide" onRequestClose={onClose}><View style={{flex:1,justifyContent:'flex-end',backgroundColor:'#0007'}}><View style={[styles.detailPad,{maxHeight:'82%',borderTopLeftRadius:20,borderTopRightRadius:20,paddingBottom:30}]}><View style={{flexDirection:'row',justifyContent:'space-between',alignItems:'center'}}><View style={{flexDirection:'row',alignItems:'center',gap:7}}><PromotionIcon type={type}/><Text style={styles.heading}>{catalog.name}</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Tarif pəncərəsini bağla" onPress={onClose}><Feather name="x" size={23} color={INK}/></Pressable></View><Text style={[styles.meta,{marginTop:5}]}>{catalog.description}</Text><Text style={[styles.formLabel,{marginTop:18,marginBottom:8}]}>Müddət və tarif · AZN</Text><ScrollView style={{maxHeight:330}}>{catalog.plans.map(option=><Pressable key={option.code} accessibilityRole="radio" accessibilityState={{checked:option.code===plan.code}} onPress={()=>{setPlanCode(option.code);intentRequestId.current='';}} style={[styles.spec,{paddingVertical:13,borderWidth:1,borderColor:option.code===plan.code?RED:LINE,borderRadius:11,paddingHorizontal:12,marginBottom:8}]}><View style={{flex:1}}><Text style={styles.specVal}>{option.label}{'popular' in option&&option.popular?' · Populyar':''}</Text><Text style={styles.meta}>{option.detail}</Text></View><Text style={[styles.specVal,{color:RED}]}>{option.price.toFixed(2)} AZN</Text></Pressable>)}</ScrollView><Text style={[styles.meta,{marginVertical:9}]}>Elan № {listing.id.slice(0,8)} · Paket yalnız ödəniş təsdiqindən sonra aktivləşir.</Text><Pressable accessibilityRole="button" disabled={busy} onPress={()=>void confirm()} style={[styles.button,busy&&{opacity:.6}]}><Text style={styles.buttonText}>{busy?'Sorğu yoxlanılır…':'Seçilmiş tarifi davam etdir'}</Text></Pressable></View></View></Modal>
}
