async function insertListingDraft(client:any,table:string,id:string,owner:string,payload:Record<string,any>){
 const inserted=await safeListingRequest(signal=>client.from(table).insert({id,...payload}).select('*').abortSignal(signal).single(),{timeoutMs:20_000});
 if(!inserted.error&&inserted.data)return {data:inserted.data as Record<string,any>,created:true};
 if((inserted.error as {code?:string}|null)?.code==='23505'){
  const existing=await safeListingRequest(signal=>client.from(table).select('*').eq('id',id).eq('owner_id',owner).abortSignal(signal).maybeSingle(),{retries:1,timeoutMs:15_000});
  if(!existing.error&&existing.data)return {data:existing.data as Record<string,any>,created:false};
 }
 throw inserted.error||new Error('Qaralama yaradılmadı. Eyni elan qaralaması ilə yenidən cəhd edin.');
}

async function safeStorageRequest<T>(request:PromiseLike<T>,timeoutMs=15_000):Promise<T|{data:null;error:unknown}>{
 try{return await withListingTimeout(request,timeoutMs);}catch(error){return {data:null,error};}
}

