 if(!userId)return <ScrollView style={styles.screen} contentContainerStyle={styles.form}><Text style={styles.brand}>A-USTA hesabı</Text><Text style={styles.muted}>Elan yerləşdirmək və redaktə etmək üçün daxil olun.</Text><TextInput value={email} onChangeText={setEmail} autoCapitalize="none" keyboardType="email-address" placeholder="E-poçt" style={styles.field}/><TextInput value={password} onChangeText={setPassword} secureTextEntry placeholder="Şifrə" style={styles.field}/>{!!error&&<Text style={styles.error}>{error}</Text>}<Pressable disabled={saving} onPress={()=>void authenticate()} style={styles.button}><Text style={styles.buttonText}>{saving?'Gözləyin…':authMode==='signIn'?'Daxil ol':'Hesab yarat'}</Text></Pressable><Pressable onPress={()=>setAuthMode(mode=>mode==='signIn'?'signUp':'signIn')} style={styles.flatButton}><Text style={styles.link}>{authMode==='signIn'?'Qeydiyyatdan keç':'Girişə qayıt'}</Text></Pressable></ScrollView>;
 return <ScrollView ref={formScroll} style={styles.screen} contentContainerStyle={styles.form}>{!draftId&&drafts.length>0&&<View style={{gap:8}}><Text style={styles.heading}>Qaralamalarım</Text>{drafts.map(row=><Pressable key={`${row._draftSource}:${row.id}`} onPress={()=>editDraft(row)} style={styles.detailPad}><Text style={styles.formLabel}>{row.brand||row.dealer_name||row.title||row.name||row.category||'Yeni elan'} · {row.status==='draft'?'Qaralama':'Gözləyir'}</Text><Text style={styles.meta}>{row.id.slice(0,8)}</Text></Pressable>)}</View>}<Text style={styles.brand}>{draftId?'Elanı redaktə et':'Yeni elan'}</Text>{!!validationField&&!!error&&<Text accessibilityRole="alert" style={styles.error}>{error}</Text>}<Text style={styles.muted}>Kateqoriya seçin</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.pills}>{CATEGORIES.map(c=><Pressable key={c.key} onPress={()=>{setKey(c.key);setDraftId('');setDraftStatus('');setValues({});setAssets([]);setSellerProfileId('');setFormStep(0);setCleanupPending(false);setEquipmentSearch('');}} style={[styles.pill,key===c.key&&styles.pillOn]}><Text style={[styles.pillText,key===c.key&&styles.pillTextOn]}>{c.title}</Text></Pressable>)}</ScrollView>
 {formStep===0&&<View style={styles.detailPad}><Text style={styles.formLabel}>Satıcı profili</Text><Pressable onPress={()=>setSellerProfileId('')} style={[styles.pill,!sellerProfileId&&styles.pillOn,{alignSelf:'flex-start',marginTop:8}]}><Text style={[styles.pillText,!sellerProfileId&&styles.pillTextOn]}>Şəxsi elan</Text></Pressable>{eligibleSellerProfiles.map(profile=><Pressable key={profile.id} onPress={()=>setSellerProfileId(profile.id)} style={[styles.pill,sellerProfileId===profile.id&&styles.pillOn,{alignSelf:'flex-start',marginTop:8}]}><Text style={[styles.pillText,sellerProfileId===profile.id&&styles.pillTextOn]}>{profile.display_name} · Təsdiqlənmiş</Text></Pressable>)}{eligibleSellerProfiles.length===0&&<Text style={styles.muted}>Bu kateqoriya üçün təsdiqlənmiş profil tapılmadı. Şəxsi elan seçimi mövcuddur; server yekun uyğunluğu özü yoxlayır.</Text>}</View>}
 {formStep===0&&fields.map(([field,label])=><View key={field} onLayout={event=>{fieldOffsets.current[field]=event.nativeEvent.layout.y;}}><Text style={[styles.formLabel,validationField===field&&{color:RED}]}>{label}</Text>{field==='currency'?<View style={{flexDirection:'row',gap:8,marginTop:5}}>{(['AZN','USD','EUR'] as const).map(code=><Pressable key={code} accessibilityRole="radio" accessibilityState={{checked:(values.currency||'AZN')===code}} onPress={()=>set('currency',code)} style={[styles.pill,(values.currency||'AZN')===code&&styles.pillOn,{flex:1,alignItems:'center'}]}><Text style={[styles.pillText,(values.currency||'AZN')===code&&styles.pillTextOn]}>{code}</Text></Pressable>)}</View>:category.source==='vehicle'&&field==='brand'?<CatalogPicker title="Marka seçin" value={values.brand||''} options={vehicleCatalog.brands} onChange={v=>{set('brand',v);set('model','');}}/>:category.source==='vehicle'&&field==='model'&&values.brand?<CatalogPicker title="Model seçin" value={values.model||''} options={vehicleModels[values.brand]||[]} onChange={v=>set('model',v)}/>:listingFieldChoices(key,field)?<ChoicePicker title={label} value={values[field]||''} options={listingFieldChoices(key,field)!} onChange={v=>set(field,v)}/>:<TextInput ref={node=>{fieldInputs.current[field]=node;}} value={values[field]||''} onChangeText={v=>set(field,v)} placeholder={label} placeholderTextColor="#98A1AB" multiline={['description','address'].includes(field)} keyboardType={field==='price'||field==='year'||field==='mileage'||field==='engine_volume'?'decimal-pad':'default'} style={[styles.field,{marginTop:5,minHeight:['description','address'].includes(field)?76:43,textAlignVertical:'top',paddingTop:12,borderColor:validationField===field?RED:LINE}]}/>}</View>)}{formStep===0&&equipmentOptions(key).length>0&&<View style={styles.detailPad}><Text style={styles.formLabel}>Avadanlıq və təchizat</Text><TextInput accessibilityLabel="Avadanlıq axtar" value={equipmentSearch} onChangeText={setEquipmentSearch} placeholder="Avadanlıq axtar" placeholderTextColor="#98A1AB" style={[styles.field,{marginTop:8}]}/><View style={[styles.row,{marginTop:10}]}>{equipmentOptions(key).filter(option=>option.toLocaleLowerCase('az-AZ').includes(equipmentSearch.trim().toLocaleLowerCase('az-AZ'))).map(option=>{const checked=selectedEquipment(values.equipment,key).includes(option);return <Pressable key={option} accessibilityRole="checkbox" accessibilityState={{checked}} onPress={()=>set('equipment',equipmentValue(values.equipment,key,option))} style={[styles.pill,checked&&styles.pillOn]}><Text style={[styles.pillText,checked&&styles.pillTextOn]}>{option}</Text></Pressable>;})}</View></View>}{formStep===0&&key==='cars'&&<View style={styles.detailPad}><Text style={styles.formLabel}>Elan imkanları</Text>{([['credit_available','Kredit mümkündür'],['barter_available','Barter mümkündür']] as [string,string][]).map(([field,label])=><View key={field} style={[styles.row,{alignItems:'center',justifyContent:'space-between',marginTop:9}]}><Text style={styles.formLabel}>{label}</Text><View style={styles.row}>{[['true','Bəli'],['false','Xeyr']].map(([value,title])=><Pressable key={value} onPress={()=>set(field,value)} style={[styles.pill,values[field]===value&&styles.pillOn]}><Text style={[styles.pillText,values[field]===value&&styles.pillTextOn]}>{title}</Text></Pressable>)}</View></View>)}</View>}
  {formStep===1&&<View style={{gap:10}}><Text style={styles.heading}>Şəkillər və video</Text><Text style={styles.muted}>Qalereyadan seçin və ya birbaşa kamera ilə çəkin. Veb formadakı media seçimi qaydası tətbiq olunur; dövlət nömrəsi kateqoriyasında video qəbul edilmir.</Text><View style={styles.row}><Pressable onPress={()=>void capture()} style={[styles.mediaPick,{flex:1,minWidth:140}]}><Feather name="camera" size={20} color={RED}/><Text style={styles.formLabel}>Kamera ilə çək</Text></Pressable><Pressable onPress={()=>void pick()} style={[styles.mediaPick,{flex:1,minWidth:140}]}><Feather name="image" size={20} color={RED}/><Text style={styles.formLabel}>Qalereyadan seç</Text></Pressable></View>{assets.map((asset,n)=><View key={asset.assetId||asset.uri} style={[styles.detailPad,{flexDirection:'row',alignItems:'center',gap:10,flexWrap:'wrap'}]}>{asset.type==='video'?<PromoVideo url={asset.uri}/>:<Image source={{uri:asset.uri}} style={{width:64,height:56,borderRadius:8}}/>}<Text style={[styles.meta,{flex:1,minWidth:100}]}>{asset.fileName||`Media ${n+1}`}</Text><Pressable onPress={()=>setAssets(list=>list.filter((_,i)=>i!==n))}><Text style={styles.link}>Sil</Text></Pressable></View>)}</View>}
  {formStep===2&&<View style={{gap:10}}><Text style={styles.heading}>Elan önizləməsi</Text><View style={styles.detailPad}>{assets[0]&&<>{assets[0].type==='video'?<PromoVideo url={assets[0].uri}/>:<Image source={{uri:assets[0].uri}} style={{width:'100%',height:190,borderRadius:12}}/>}</>}<Text style={styles.badge}>{category.title}</Text><Text style={styles.detailPrice}>{formatListingPrice(values.price||values.daily_price,values.currency||'AZN',exchangeRates,displayCurrency)}</Text><Text style={styles.detailTitle}>{values.title||[values.brand,values.model,values.year].filter(Boolean).join(' ')||category.title}</Text><Text style={styles.meta}>{[values.year,values.engine_volume?`${values.engine_volume} L`:null,values.mileage?`${values.mileage} km`:null,values.region,values.district].filter(Boolean).join(' · ')}</Text><Text style={styles.meta}>{values.description||values.about||'Təsvir əlavə edilməyib.'}</Text></View><Text style={styles.muted}>Dərc etməzdən əvvəl məlumatları yoxlayın. Server tərəfi RLS, sahiblik və kateqoriya qaydaları qüvvədə qalır.</Text></View>}
  {!!error&&<Text accessibilityRole="alert" style={styles.error}>{error}</Text>}{!!progress&&<Text style={styles.muted}>{progress}</Text>}
  {cleanupPending&&<Text accessibilityRole="alert" style={styles.error}>Media təmizlənməsi təsdiqlənmədi. Təkrar yükləməni dayandırdıq; əvvəlcə bu qaralamanı dəstək vasitəsilə yoxlatdırın.</Text>}<View style={styles.row}>{formStep>0&&<Pressable disabled={saving} onPress={()=>setFormStep(v=>Math.max(0,v-1))} style={[styles.outline,{flex:1}]}><Text style={styles.outlineText}>Geri</Text></Pressable>}<Pressable disabled={saving||cleanupPending} onPress={()=>void save(false)} style={[styles.outline,{flex:1}]}><Text style={styles.outlineText}>{saving?'Saxlanılır…':draftStatus==='active'?'Dəyişiklikləri saxla':'Qaralama saxla'}</Text></Pressable></View>{formStep<2?<Pressable disabled={saving||cleanupPending} onPress={advanceStep} style={styles.button}><Text style={styles.buttonText}>Davam et · {['Məlumatlar','Media','Önizləmə'][formStep+1]}</Text></Pressable>:<Pressable disabled={saving||cleanupPending} onPress={()=>void save(true)} style={styles.button}><Text style={styles.buttonText}>{saving?'Gözləyin…':draftStatus==='active'?'Elanı yenilə':'Dərc et'}</Text></Pressable>}
 </ScrollView>;
